.darma-loader-tw-counter-rings { position: relative; display: inline-block; width: var(--loader-size, 64px); height: var(--loader-size, 64px); }
.darma-loader-tw-counter-rings span { position: absolute; border-radius: 9999px; border: calc(var(--loader-size, 64px) * .05) solid transparent; }
.darma-loader-tw-counter-rings span:nth-child(1) { top: 0; bottom: 0; left: 0; right: 0; border-top-color: var(--loader-color, #6366f1); animation: darma-loader-tw-counter-rings-twSpin var(--loader-speed, 1s) linear infinite; }
.darma-loader-tw-counter-rings span:nth-child(2) { top: 18%; bottom: 18%; left: 18%; right: 18%; border-right-color: var(--loader-secondary-color, #06b6d4); animation: darma-loader-tw-counter-rings-twSpinBack calc(var(--loader-speed, 1s) * .85) linear infinite; }
.darma-loader-tw-counter-rings span:nth-child(3) { top: 36%; bottom: 36%; left: 36%; right: 36%; border-bottom-color: var(--loader-color, #6366f1); animation: darma-loader-tw-counter-rings-twSpin calc(var(--loader-speed, 1s) * .7) linear infinite; }
@keyframes darma-loader-tw-counter-rings-twSpin { to { transform: rotate(360deg); } }
@keyframes darma-loader-tw-counter-rings-twSpinBack { to { transform: rotate(-360deg); } }

